/// The curated entry for a tree row: a directory, a `.d.ts`, a known
/// filename, a known extension — else null.
pub fn rowEntry(arena: Allocator, label: []const u8, is_dir: bool) Allocator.Error!?Entry {
    if (is_dir) return .{
        .title = try std.fmt.allocPrint(arena, "{s}/", .{label}),
        .body = "Directory. Enter or click to expand; walk the tree with arrows or j/k. Right-click for rename / cut / copy / new file.",
        .keys = &dir_keys,
        .links = &.{ .{ .command = .{ .id = .@"file.new", .label = "New file here" } }, .{ .command = .{ .id = .@"files.open", .label = "Open as a Files pane" } } },
    };
    var buf: [256]u8 = undefined;
    if (label.len > buf.len) return null;
    const lower = std.ascii.lowerString(&buf, label);
    if (std.mem.endsWith(u8, lower, ".d.ts")) return .{
        .title = try std.fmt.allocPrint(arena, "{s} — TypeScript declarations", .{label}),
        .body = "`.d.ts` — TypeScript type declarations. No runtime code; describes the shape of a JS module for tsserver to consume. Editing here changes types, not behavior.",
        .keys = &open_keys,
        .links = &file_links,
    };
    for (by_name) |r| if (std.mem.eql(u8, r.key, lower)) return .{
        .title = try std.fmt.allocPrint(arena, "{s} — {s}", .{ label, r.lang }),
        .body = r.body,
        .keys = &open_keys,
        .links = &file_links,
    };
    const ext = icons.extensionOf(lower) orelse return null;
    for (by_ext) |r| if (std.mem.eql(u8, r.key, ext)) return .{
        .title = try std.fmt.allocPrint(arena, "{s} — {s}", .{ label, r.lang }),
        .body = r.body,
        .keys = &open_keys,
        .links = &file_links,
    };
    return null;
}

const file_links = [_]copy.Link{ .{ .command = .{ .id = .@"tree.open_selected", .label = "Open it" } }, .{ .command = .{ .id = .@"tree.open_in_split", .label = "Open in a split" } } };

/// The entry for a tree row, curated or the generic line — never null
/// for a row that exists, so the audit counts an unknown extension as
/// curated-by-family rather than a gap.
pub fn rowOrGeneric(arena: Allocator, name: []const u8, is_dir: bool) Allocator.Error!Entry {
    if (try rowEntry(arena, name, is_dir)) |e| return e;
    return .{
        .title = name,
        .body = "A file the dictionary has no words for yet — mnml opens it as text with the highlighter its extension maps to, or none. Enter opens it in a new tab; right-click for cut / copy / paste / rename; drag it onto a folder to move it.",
        .keys = &open_keys,
        .links = &file_links,
    };
}

pub fn node(app: *App, arena: Allocator, idx: u32) Allocator.Error!?Entry {
    if (idx >= app.tree.rows.items.len) return null;
    const row = app.tree.rows.items[idx];
    if (row.header) return try root(app, arena, 0);
    return try rowOrGeneric(arena, row.name(), row.is_dir);
}

pub fn root(app: *App, arena: Allocator, r: u8) Allocator.Error!?Entry {
    if (r == 0) return .{
        .title = "Workspace root",
        .body = "Names the folder the tree is rooted at — click to collapse or expand the whole tree, Alt+click to fold or open every directory. The chips on the row make a folder or a file, pull, fold every directory, and rescan. Right-click is the workspace menu: a new file or folder, add, switch or manage workspaces, copy the path, refresh.",
        .keys = &.{.{ .chord = "Alt+click", .label = "Fold / open every directory" }},
        .links = &.{ .{ .command = .{ .id = .@"view.add_workspace", .label = "Add a workspace root" } }, .{ .command = .{ .id = .@"view.switch_workspace", .label = "Switch workspace" } } },
    };
    if (r - 1 < app.tree.roots.items.len) return .{
        .title = try std.fmt.allocPrint(arena, "Workspace: {s}", .{app.tree.roots.items[r - 1].name}),
        .body = "An extra workspace root from `workspaces` in config.zon, as a second section of the tree. Click to open or fold its tree; `view.switch_workspace` makes it the one open, with its own session and `.mnml/`. Its files open like any other; git follows the repo they are in.",
        .keys = &.{ .{ .chord = "Enter", .label = "Open / fold the section" }, .{ .command = .@"view.switch_workspace", .label = "Make it the workspace" } },
        .links = &.{ .{ .command = .{ .id = .@"view.switch_workspace", .label = "Switch to it" } }, .{ .command = .{ .id = .@"view.remove_workspace", .label = "Remove a root" } } },
    };
    return null;
}

pub fn empty() Entry {
    return .{
        .title = "Workspace — the empty rows",
        .body = "The tree's rows below the last file. A click here focuses the tree without picking a row; right-click opens the workspace menu — a new file or folder at the root, add, switch or manage workspaces — the same rows the root's header offers. Drop a file here to move it to the root.",
        .keys = &.{ .{ .chord = "Right-click", .label = "The workspace menu" }, .{ .command = .@"file.new", .label = "New file at the root" } },
        .links = &.{ .{ .command = .{ .id = .@"file.new", .label = "New file" } }, .{ .command = .{ .id = .@"file.new_folder", .label = "New folder" } } },
    };
}

/// A header chip's copy (Rust `TreeIcon`), with a `Run it` link.
pub fn chip(c: tree_view.Chip) Entry {
    return switch (c) {
        inline else => |cc| chipEntry(cc),
    };
}

/// The chip's entry with `id` comptime-known, so the links array is
/// static data rather than a stack temporary the caller would outlive.
fn chipEntry(comptime c: tree_view.Chip) Entry {
    const id = comptime tree_mod.chipCommand(c);
    return switch (c) {
        .new_file => .{ .title = "New file", .body = "Creates an empty file in the workspace root and opens it in a fresh tab, prompting for a name first. A name with a slash makes the folders on the way; a name that exists opens that file instead.", .links = &.{ .{ .command = .{ .id = id, .label = "Run it" } }, .{ .command = .{ .id = .@"file.new_folder", .label = "New folder instead" } } } },
        .new_folder => .{ .title = "New folder", .body = "Creates a new directory in the workspace root after prompting for a name. The tree jumps to show it; a name with a slash makes every folder on the way.", .links = &.{ .{ .command = .{ .id = id, .label = "Run it" } }, .{ .command = .{ .id = .@"file.new", .label = "New file instead" } } } },
        .refresh => .{ .title = "Refresh tree", .body = "Re-scans the workspace root from disk and repaints the tree — use it after external changes mnml's file-watcher might have missed (bulk git operations, another process writing files). Open folders stay open; the cursor stays on its row when the row survives.", .links = &.{ .{ .command = .{ .id = id, .label = "Run it" } }, .{ .command = .{ .id = .@"git.refresh", .label = "Refresh git too" } } } },
        .collapse => .{ .title = "Collapse / expand all", .body = "Folds every open directory in the tree closed, or opens every directory when the tree is already fully collapsed. One click toggles the whole rail; the chip's glyph says which way the next click goes.", .links = &.{ .{ .command = .{ .id = id, .label = "Run it" } }, .{ .command = .{ .id = .@"tree.expand_all", .label = "Expand every directory" } } } },
        .pull => .{ .title = "Pull (workspace header)", .body = "Runs `git pull --ff-only` against the repo that owns this workspace root, right from the tree header, and toasts the result. A pull that would need a merge stops and says so — the git palette's rows are where the merge happens.", .links = &.{ .{ .command = .{ .id = id, .label = "Run it" } }, .{ .command = .{ .id = .@"git.push", .label = "Push" } }, ask } },
        .add_workspace => .{ .title = "Add workspace folder", .body = "Opens a path prompt to add another folder as an extra workspace root alongside the current one — the tree grows a second top-level section instead of replacing what's open. Type a path (`~` expands); missing intermediate folders are NOT created here. The root is written to `workspaces` in config.zon.", .links = &.{ .{ .command = .{ .id = id, .label = "Run it" } }, .{ .command = .{ .id = .@"view.manage_workspaces", .label = "Manage the workspaces" } } } },
    };
}

// ─── tests ──────────────────────────────────────────────────────────────

const t = std.testing;

test "the dictionary: a directory, package.json, a .d.ts, a plain .txt, and an unknown extension" {
    var arena_state: std.heap.ArenaAllocator = .init(t.allocator);
    defer arena_state.deinit();
    const a = arena_state.allocator();
    const dir = (try rowEntry(a, "src", true)).?;
    try t.expectEqualStrings("src/", dir.title);
    try t.expectEqual(@as(usize, 2), dir.keys.len);
    try t.expectEqualStrings("Enter", dir.keys[0].chord);
    const pkg = (try rowEntry(a, "Package.JSON", false)).?;
    try t.expectEqualStrings("Package.JSON — npm manifest", pkg.title);
    const dts = (try rowEntry(a, "types.d.ts", false)).?;
    try t.expectEqualStrings("types.d.ts — TypeScript declarations", dts.title);
    const txt = (try rowEntry(a, "notes.txt", false)).?;
    try t.expectEqualStrings("notes.txt — Plain text", txt.title);
    // `tree.open_in_split` has no chord in either profile, so the row
    // names only Enter — the split is the row menu's *Open in split*.
    try t.expectEqual(@as(usize, 1), txt.keys.len);
    try t.expect((try rowEntry(a, "weird.xyz", false)) == null);
    try t.expectEqualStrings("weird.xyz", (try rowOrGeneric(a, "weird.xyz", false)).title);
    try t.expect((try rowEntry(a, "Makefile", false)) != null);
    // Every dictionary key is lower-case and unique within its table.
    inline for (.{ by_name, by_ext }) |table| for (table, 0..) |r, i| {
        for (r.key) |c| try t.expect(!std.ascii.isUpper(c));
        for (table[0..i]) |prev| try t.expect(!std.mem.eql(u8, prev.key, r.key));
        try t.expect(r.body.len > 20);
    };
    // Every chip has an entry with its command as the first link.
    inline for (comptime std.enums.values(tree_view.Chip)) |c| try t.expectEqual(tree_mod.chipCommand(c), chip(c).links[0].command.id);
}
